css:
:root{
  --blue:#016edc; --blue-dark:#014284; --navy:#1c293f; --deep:#00334e;
  --amber:#ffa800; --amber-ink:#3d2900;
  --light:#f0f0fa; --soft:#f5f5f5; --line:#e5e7eb;
  --ink:#1c293f; --body:#3a4658; --white:#ffffff;
  --r-sm:16px; --r-md:30px; --r-lg:60px;
  --shadow:0 20px 50px rgba(28,41,63,.10);
  --shadow-sm:0 8px 22px rgba(28,41,63,.08);
  --max:1200px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:'Fustat',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
  color:var(--body);background:var(--white);line-height:1.65;font-size:17px;font-weight:400}
h1,h2,h3,h4{color:var(--ink);line-height:1.15;margin:0 0 .5em;font-weight:800;letter-spacing:-.01em}
h1{font-size:clamp(2rem,4.4vw,3.15rem)}
h2{font-size:clamp(1.55rem,3vw,2.3rem)}
h3{font-size:1.2rem;font-weight:700}
p{margin:0 0 1.05em}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;display:block}
.container{max-width:var(--max);margin:0 auto;padding:0 22px}
.eyebrow{display:inline-block;font-weight:800;letter-spacing:.12em;text-transform:uppercase;
  font-size:.74rem;color:var(--blue);margin-bottom:14px}
.eyebrow.on-dark{color:var(--amber)}
.skip{position:absolute;left:-999px;top:0;background:var(--amber);color:var(--amber-ink);
  padding:10px 16px;border-radius:0 0 12px 0;z-index:200;font-weight:700}
.skip:focus{left:0}
/* buttons */
.btn{display:inline-flex;align-items:center;gap:.55em;font-weight:800;border-radius:999px;
  padding:15px 26px;font-size:1rem;cursor:pointer;border:2px solid transparent;transition:.18s;text-decoration:none}
.btn:hover{text-decoration:none;transform:translateY(-2px)}
.btn-amber{background:var(--amber);color:var(--amber-ink)}
.btn-amber:hover{background:#ffb92e;box-shadow:0 12px 26px rgba(255,168,0,.35)}
.btn-blue{background:var(--blue);color:#fff}
.btn-blue:hover{background:#0a63bd}
.btn-ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-ghost:hover{background:rgba(255,255,255,.12)}
.btn-outline{background:#fff;color:var(--blue-dark);border-color:var(--line)}
.btn-outline:hover{border-color:var(--blue)}
.btn-lg{padding:17px 32px;font-size:1.05rem}
/* utility bar */
.utility{background:var(--navy);color:#d6def0;font-size:.86rem}
.utility .container{display:flex;justify-content:space-between;align-items:center;gap:14px;min-height:42px;flex-wrap:wrap}
.utility .u-facts{display:flex;gap:20px;flex-wrap:wrap;align-items:center}
.utility .u-facts span{display:inline-flex;gap:.5em;align-items:center}
.utility i{color:var(--amber)}
.utility a{color:#fff;font-weight:700}
/* header */
header.site{position:sticky;top:0;z-index:120;background:rgba(255,255,255,.96);
  backdrop-filter:saturate(1.2) blur(6px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:76px}
.brand img{height:46px;width:auto}
.menu{display:flex;align-items:center;gap:4px;list-style:none;margin:0;padding:0}
.menu>li{position:relative}
.menu>li>a{display:block;padding:12px 14px;color:var(--ink);font-weight:700;font-size:.96rem;border-radius:10px}
.menu>li>a:hover{background:var(--light);text-decoration:none;color:var(--blue-dark)}
.has-drop>a:after{content:"\f078";font-family:"Font Awesome 6 Free";font-weight:900;font-size:.6rem;margin-left:.5em;opacity:.6}
.drop{position:absolute;top:100%;left:0;min-width:250px;background:#fff;border:1px solid var(--line);
  border-radius:14px;box-shadow:var(--shadow);padding:8px;display:none;list-style:none;margin:6px 0 0}
.drop li a{display:block;padding:10px 14px;border-radius:9px;color:var(--ink);font-weight:600;font-size:.92rem}
.drop li a:hover{background:var(--light);text-decoration:none;color:var(--blue-dark)}
.has-drop:hover .drop,.has-drop:focus-within .drop{display:block}
.nav-cta{display:flex;align-items:center;gap:12px}
.nav-call{display:inline-flex;align-items:center;gap:.5em;font-weight:800;color:var(--blue-dark)}
.nav-call:hover{text-decoration:none}
.burger{display:none;background:none;border:0;font-size:1.5rem;color:var(--ink);cursor:pointer;padding:8px}
/* breadcrumb */
.crumb{background:var(--soft);border-bottom:1px solid var(--line);font-size:.86rem}
.crumb .container{padding-top:12px;padding-bottom:12px}
.crumb ol{list-style:none;display:flex;flex-wrap:wrap;gap:.5em;margin:0;padding:0;color:#6a7688}
.crumb li:not(:last-child):after{content:"\f105";font-family:"Font Awesome 6 Free";font-weight:900;margin-left:.55em;color:#aab3c2}
.crumb a{color:var(--blue-dark);font-weight:700}
.crumb li[aria-current]{color:var(--ink);font-weight:700}
/* hero */
.hero{position:relative;color:#fff;background:linear-gradient(115deg,var(--blue-dark) 0%,var(--blue) 55%,#0a63bd 100%);overflow:hidden}
.hero:before{content:"";position:absolute;inset:0;background:
  radial-gradient(900px 500px at 88% -10%,rgba(255,168,0,.20),transparent 60%);pointer-events:none}
.hero .container{position:relative;display:grid;grid-template-columns:1.15fr .85fr;gap:44px;align-items:center;
  padding-top:64px;padding-bottom:64px}
.hero h1{color:#fff}
.hero .lede{font-size:1.16rem;color:#e7eefc;max-width:38ch}
.chips{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 26px;padding:0;list-style:none}
.chips li{display:inline-flex;align-items:center;gap:.55em;background:rgba(255,255,255,.12);
  border:1px solid rgba(255,255,255,.22);padding:9px 15px;border-radius:999px;font-weight:700;font-size:.88rem;color:#fff}
.chips i{color:var(--amber)}
.hero-actions{display:flex;flex-wrap:wrap;gap:14px;align-items:center}
.hero-media{position:relative}
/* image placeholders */
.imgph{position:relative;border-radius:var(--r-sm);border:2px dashed #9bb4d6;background:
  repeating-linear-gradient(45deg,#eef3fb,#eef3fb 12px,#e6edf8 12px,#e6edf8 24px);
  display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;
  color:#3f567f;padding:18px;min-height:150px}
.imgph .tag{font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:.72rem;color:var(--blue-dark);
  background:#fff;border:1px solid #c7d6ee;border-radius:999px;padding:4px 12px;margin-bottom:10px}
.imgph .desc{font-size:.82rem;max-width:34ch;line-height:1.45}
.imgph .dims{font-size:.72rem;color:#6d7f9c;margin-top:8px;font-weight:600}
.hero-media .imgph{min-height:330px;background:
  repeating-linear-gradient(45deg,rgba(255,255,255,.14),rgba(255,255,255,.14) 12px,rgba(255,255,255,.06) 12px,rgba(255,255,255,.06) 24px);
  border-color:rgba(255,255,255,.5);color:#fff}
.hero-media .imgph .tag{background:rgba(255,255,255,.16);color:#fff;border-color:rgba(255,255,255,.4)}
.hero-media .imgph .dims{color:#dfe8fb}
/* trust band */
.trustband{background:var(--navy);color:#fff}
.trustband .container{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;padding-top:30px;padding-bottom:30px}
.trustband .t{display:flex;gap:14px;align-items:flex-start}
.trustband .t i{font-size:1.5rem;color:var(--amber);margin-top:2px}
.trustband .t strong{display:block;color:#fff;font-size:1.02rem}
.trustband .t span{font-size:.85rem;color:#c2ccde}
/* sections */
section{padding:64px 0}
.sec-tint{background:var(--light)}
.sec-soft{background:var(--soft)}
.sec-navy{background:var(--navy);color:#e9eefb}
.sec-navy h2,.sec-navy h3{color:#fff}
.sec-blue{background:linear-gradient(120deg,var(--blue-dark),var(--blue));color:#fff}
.sec-blue h2,.sec-blue h3{color:#fff}
.sec-head{max-width:720px;margin-bottom:38px}
.sec-head.center{margin-left:auto;margin-right:auto;text-align:center}
.sec-head p{font-size:1.08rem}
.lead{font-size:1.12rem;color:var(--ink);font-weight:600}
/* grids + cards */
.grid{display:grid;gap:22px}
.g2{grid-template-columns:repeat(2,1fr)}
.g3{grid-template-columns:repeat(3,1fr)}
.g4{grid-template-columns:repeat(4,1fr)}
.card{background:#fff;border:1px solid var(--line);border-radius:var(--r-sm);padding:26px;box-shadow:var(--shadow-sm);transition:.18s}
.card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:#cfe0f7}
.card .ic{width:52px;height:52px;border-radius:14px;background:var(--light);color:var(--blue);
  display:flex;align-items:center;justify-content:center;font-size:1.3rem;margin-bottom:16px}
.card h3{margin-bottom:.4em}
.card p{font-size:.95rem;margin-bottom:0}
.card.on-navy{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.14)}
.card.on-navy .ic{background:rgba(255,168,0,.16);color:var(--amber)}
.card.on-navy p{color:#c8d2e6}
.card .more{display:inline-flex;gap:.4em;align-items:center;font-weight:800;font-size:.9rem;margin-top:14px}
/* feature list (checks) */
.checks{list-style:none;padding:0;margin:0;display:grid;gap:14px}
.checks.two{grid-template-columns:1fr 1fr}
.checks li{display:flex;gap:12px;align-items:flex-start;font-size:.98rem}
.checks li i{color:var(--blue);margin-top:5px;font-size:.95rem;flex:none}
.sec-navy .checks li i,.sec-blue .checks li i{color:var(--amber)}
/* split feature */
.split{display:grid;grid-template-columns:1fr 1fr;gap:52px;align-items:stretch}
.split .txt{min-width:0;align-self:center}
.split .txt:has(.imgph){align-self:stretch}
.split .txt .imgph{height:100%;min-height:320px}
.split.flip .txt{order:2}
/* process steps */
.steps{counter-reset:s;display:grid;gap:20px;grid-template-columns:repeat(4,1fr)}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--r-sm);padding:26px 22px}
.step:before{counter-increment:s;content:counter(s);position:absolute;top:-18px;left:22px;width:40px;height:40px;
  background:var(--amber);color:var(--amber-ink);border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800}
.step h3{margin-top:8px;font-size:1.05rem}
.step p{font-size:.9rem;margin-bottom:0}
/* capability table */
.captable{width:100%;border-collapse:collapse;background:#fff;border-radius:var(--r-sm);overflow:hidden;box-shadow:var(--shadow-sm)}
.captable th,.captable td{text-align:left;padding:15px 18px;border-bottom:1px solid var(--line);font-size:.95rem;vertical-align:top}
.captable th{background:var(--navy);color:#fff;font-size:.82rem;letter-spacing:.05em;text-transform:uppercase}
.captable tr:last-child td{border-bottom:0}
.captable td i{color:var(--blue);margin-right:.5em}
/* callout */
.callout{background:#fff;border:1px solid var(--line);border-left:5px solid var(--amber);border-radius:14px;padding:22px 24px;box-shadow:var(--shadow-sm)}
/* reviews */
.rev{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.review{background:#fff;border:1px solid var(--line);border-radius:var(--r-sm);padding:24px;box-shadow:var(--shadow-sm)}
.review .stars{color:var(--amber);margin-bottom:10px}
.review p{font-style:italic;color:var(--ink);font-size:.96rem}
.review .who{font-weight:800;color:var(--ink);font-style:normal;font-size:.9rem;margin-top:10px}
.review .who span{display:block;font-weight:600;color:#7a869a;font-size:.8rem}
/* form */
.formwrap{background:#fff;border:1px solid var(--line);border-radius:var(--r-md);padding:32px;box-shadow:var(--shadow)}
.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.field{display:flex;flex-direction:column;gap:6px}
.field.full{grid-column:1 / -1}
.field label{font-weight:700;font-size:.85rem;color:var(--ink)}
.field input,.field textarea{font:inherit;font-size:.98rem;padding:13px 15px;border:1.5px solid var(--line);
  border-radius:12px;background:#fcfdff;color:var(--ink)}
.field textarea{min-height:110px;resize:vertical}
.field input:focus,.field textarea:focus{outline:3px solid rgba(1,110,220,.25);border-color:var(--blue)}
.form-note{font-size:.8rem;color:#7a869a;margin:14px 0 0;display:flex;gap:.5em;align-items:flex-start}
.aside-book{background:linear-gradient(135deg,var(--navy),var(--deep));color:#fff;border-radius:var(--r-md);padding:32px}
.aside-book h2{color:#fff}
.aside-book .checks li{color:#dfe6f4}
.aside-book .checks li i{color:var(--amber)}
.book-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:34px;align-items:start}
/* faq */
.faq details{background:#fff;border:1px solid var(--line);border-radius:14px;margin-bottom:12px;overflow:hidden}
.faq summary{list-style:none;cursor:pointer;padding:18px 22px;font-weight:700;color:var(--ink);
  display:flex;justify-content:space-between;gap:16px;align-items:center}
.faq summary::-webkit-details-marker{display:none}
.faq summary:after{content:"\f067";font-family:"Font Awesome 6 Free";font-weight:900;color:var(--blue);font-size:.85rem;flex:none}
.faq details[open] summary:after{content:"\f068"}
.faq details[open] summary{color:var(--blue-dark)}
.faq .a{padding:0 22px 20px;font-size:.96rem}
.faq .a p:last-child{margin-bottom:0}
/* final cta */
.finalcta{background:linear-gradient(120deg,var(--blue-dark),var(--blue));color:#fff;text-align:center}
.finalcta h2{color:#fff}
.finalcta p{color:#e7eefc;max-width:60ch;margin-left:auto;margin-right:auto;font-size:1.1rem}
.finalcta .hero-actions{justify-content:center;margin-top:26px}
/* footer */
footer.site{background:var(--navy);color:#c2ccde;font-size:.92rem}
footer.site .container{padding-top:56px;padding-bottom:28px}
.foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:34px}
footer.site img{height:42px;margin-bottom:16px}
footer.site h4{color:#fff;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase;margin-bottom:16px}
footer.site ul{list-style:none;margin:0;padding:0;display:grid;gap:10px}
footer.site a{color:#c2ccde}
footer.site a:hover{color:#fff}
.foot-contact li{display:flex;gap:.7em;align-items:flex-start}
.foot-contact i{color:var(--amber);margin-top:4px}
.social{display:flex;gap:10px;margin-top:18px}
.social a{width:40px;height:40px;border-radius:10px;background:rgba(255,255,255,.08);display:flex;
  align-items:center;justify-content:center;color:#fff;font-size:1rem}
.social a:hover{background:var(--blue)}
.foot-bottom{border-top:1px solid rgba(255,255,255,.12);margin-top:40px;padding-top:20px;
  display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;font-size:.83rem;color:#95a2b8}
.foot-bottom a{color:#95a2b8}
/* responsive */
@media(max-width:1000px){
  .hero .container{grid-template-columns:1fr;gap:30px}
  .hero-media{order:-1}
  .g4{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:repeat(2,1fr);gap:34px 20px}
  .foot-grid{grid-template-columns:1fr 1fr}
  .book-grid{grid-template-columns:1fr}
  .trustband .container{grid-template-columns:1fr 1fr;gap:20px}
}
@media(max-width:820px){
  .menu,.nav-call{display:none}
  .burger{display:block}
  .mobile-open .menu{display:flex;position:absolute;top:100%;left:0;right:0;flex-direction:column;
    background:#fff;border-bottom:1px solid var(--line);padding:10px;gap:2px;box-shadow:var(--shadow)}
  .mobile-open .menu>li>a{padding:13px}
  .mobile-open .drop{display:block;position:static;box-shadow:none;border:0;padding:2px 2px 8px 16px;min-width:0}
  .split,.g2,.g3,.rev,.checks.two{grid-template-columns:1fr}
  .form-grid{grid-template-columns:1fr}
  .split.flip .txt{order:0}
}
@media(max-width:520px){
  .g4,.trustband .container,.foot-grid{grid-template-columns:1fr}
  body{font-size:16px}
  section{padding:48px 0}
}
